import{_ as a,C as i,o as l,c as u,j as r,a as o,E as s,a2 as n}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Tableau de bord","description":"","frontmatter":{"title":"Tableau de bord"},"headers":[],"relativePath":"guide/dashboard.md","filePath":"guide/dashboard.md"}'),d={name:"guide/dashboard.md"};function c(g,e,p,h,v,m){const t=i("Capture");return l(),u("div",null,[e[0]||(e[0]=r("h1",{id:"tableau-de-bord",tabindex:"-1"},[o("Tableau de bord "),r("a",{class:"header-anchor",href:"#tableau-de-bord","aria-label":'Permalink to "Tableau de bord"'},"​")],-1)),e[1]||(e[1]=r("p",null,[o("Le tableau de bord est l'écran de "),r("strong",null,"reprise"),o(" d'un workspace. Il répond à une seule question : qu'est-ce qui vous attend ? Vous y voyez en une ligne ce qui est en cours, puis la liste de ce qui demande une action de votre part, l'état du backlog et ce qui suit.")],-1)),s(t,{name:"dashboard",alt:"Le tableau de bord : la ligne En cours, Ce qui t'attend, Statistiques, À suivre et Activité récente"}),e[2]||(e[2]=n('<h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2><ul><li><strong>En cours</strong> : une seule ligne — l&#39;épic actif, la story active, la tâche en cours avec son identifiant, la phase OPALE en pastille et le compteur des tâches de la story (par exemple « 2/5 tâches »). Un clic ouvre l&#39;écran <a href="/Effortless/guide/tasks.html">Tâches</a>.</li><li><strong>Ce qui t&#39;attend</strong> : ce qui demande une action humaine, groupé par nature. Chaque section annonce son action et son compte — « À trancher : 11 questions », « À clore ou reprendre : 1 tâche », « À livrer : 1 commit » —, une phrase dit pourquoi, et chaque point montre son âge (« 52 j »), le plus ancien en tête ; au-delà de trois, <strong>+ N autres</strong> déplie le reste et <strong>Replier</strong> le referme. Le moteur y range : <ul><li>les <strong>questions ouvertes</strong>, d&#39;une story ou du projet ;</li><li>les <strong>scénarios de recette non vérifiés</strong> d&#39;une story dont la recette exige un statut de maturité ;</li><li>les <strong>tâches orphelines</strong> : une tâche restée <strong>En cours</strong> alors que sa story ou son épic est clos, ou que sa story n&#39;est pas la story active ;</li><li>les <strong>anomalies critiques</strong> (criticité 1) non résolues ;</li><li>les <strong>commits non poussés</strong>, les <strong>commits depuis la dernière version</strong> livrée, et la <strong>dérive</strong> (des fichiers de code modifiés sans tâche en cours).</li></ul></li><li><strong>Statistiques</strong> : une barre d&#39;avancement par niveau du backlog (épics, stories, tâches — « reste / total »), et une barre empilée du registre des évolutions (vivantes, en attente, closes) avec sa légende.</li><li><strong>À suivre</strong> : les cinq premières évolutions dans l&#39;ordre calculé par le moteur — pas l&#39;ordre du fichier.</li><li><strong>Activité récente</strong> : les derniers commits du dépôt.</li></ul><p>Si une source n&#39;a pas pu être lue (un dépôt sans branche amont, par exemple), le pied de <strong>Ce qui t&#39;attend</strong> le dit : « Non vérifié : … ». Rien n&#39;est tu.</p><p>Quand il n&#39;y a rien, chaque carte le dit : « Rien en cours : aucun épic actif. », « Rien ne t&#39;attend : … », « Aucune évolution vivante. », « Aucune activité. »</p><h2 id="ce-que-vous-pouvez-faire" tabindex="-1">Ce que vous pouvez faire <a class="header-anchor" href="#ce-que-vous-pouvez-faire" aria-label="Permalink to &quot;Ce que vous pouvez faire&quot;">​</a></h2><h3 id="agir-sur-un-point" tabindex="-1">Agir sur un point <a class="header-anchor" href="#agir-sur-un-point" aria-label="Permalink to &quot;Agir sur un point&quot;">​</a></h3><p>Cliquez sur une ligne de <strong>Ce qui t&#39;attend</strong> : elle ouvre l&#39;écran où l&#39;on agit — <a href="/Effortless/guide/knowledge.html">Connaissance</a> pour une question ou une recette, <a href="/Effortless/guide/backlog.html">Backlog</a> pour une tâche orpheline ou une anomalie, <a href="/Effortless/guide/git.html">Git</a>, <a href="/Effortless/guide/release.html">Livraison</a> ou <a href="/Effortless/guide/drift.html">Dérive</a> pour le reste.</p><h3 id="ouvrir-le-detail" tabindex="-1">Ouvrir le détail <a class="header-anchor" href="#ouvrir-le-detail" aria-label="Permalink to &quot;Ouvrir le détail&quot;">​</a></h3><p><strong>Statistiques</strong> et <strong>À suivre</strong> ouvrent le <a href="/Effortless/guide/backlog.html">Backlog</a> ; <strong>Activité récente</strong> ouvre <a href="/Effortless/guide/git.html">Git</a>.</p><h3 id="ajouter-des-tuiles" tabindex="-1">Ajouter des tuiles <a class="header-anchor" href="#ajouter-des-tuiles" aria-label="Permalink to &quot;Ajouter des tuiles&quot;">​</a></h3><p>Une <strong>tuile</strong> affiche les données que vous composez. Ajoutez-en autant que vous voulez : <strong>Éditer le layout</strong>, <strong>Bibliothèque…</strong>, puis <strong>Ajouter</strong> sur <strong>Tuile</strong> ; la nouvelle tuile se range au premier espace libre et l&#39;écran défile jusqu&#39;à elle. Son bouton <strong>Régler</strong> ouvre un panneau :</p><ul><li>un <strong>titre</strong> (sinon, il se déduit de la première série) ;</li><li>le <strong>style</strong> : <strong>Chiffre</strong>, <strong>Anneau</strong>, <strong>Barres</strong> ou <strong>Tendance</strong> (une courbe par série) ;</li><li>la <strong>période</strong> des flux : 7, 30 ou 90 jours ;</li><li><strong>Découper par</strong> : aucun axe, l&#39;état, le type, la criticité ou la priorité ;</li><li>la <strong>palette</strong> : Effortless, Monochrome, Contraste fort, Pastel, ou l&#39;une des vôtres (voir <a href="/Effortless/guide/preferences.html">Profil et préférences</a>) ;</li><li>les <strong>séries</strong> — autant que vous voulez. Chacune choisit son jeu (épics, stories, tâches, évolutions), ses filtres (états, types, criticité, priorité), sa <strong>mesure</strong> et sa <strong>couleur</strong> : <ul><li>comptes : total, ouverts, fermés, avancement ;</li><li>flux sur la période : créés, fermés, solde ;</li><li>âges et délais : âge moyen des ouverts, plus vieil ouvert, délai moyen de fermeture ;</li><li>pour les évolutions : criticité et priorité moyennes.</li></ul></li><li><strong>Couleurs des groupes</strong> : quand un axe découpe la tuile, chaque groupe peut recevoir sa couleur.</li></ul><p><strong>Ajouter une série</strong> en ajoute une, <strong>Retirer la série</strong> l&#39;enlève. Une couleur se prend dans la palette de la tuile, ou se choisit librement. Chaque réglage s&#39;applique aussitôt ; <strong>OK</strong> ferme le panneau, <strong>Enregistrer le layout</strong> garde la place de la tuile. Si les filtres ne retiennent rien, la tuile affiche « Pas de données pour ce type. »</p>',13)),s(t,{name:"tuile-editeur",alt:"Le panneau de réglage d'une tuile : style, période, axe, palette et séries"}),s(t,{name:"dashboard-tuile-composee",alt:"Une tuile en barres : deux séries d'évolutions découpées par criticité"}),s(t,{name:"dashboard-tuiles",alt:"Quatre tuiles : Tâches en chiffre, Évolutions en anneau, Anomalies en barres par criticité, Tâches en barres par état"}),e[3]||(e[3]=n('<h3 id="personnaliser-la-disposition" tabindex="-1">Personnaliser la disposition <a class="header-anchor" href="#personnaliser-la-disposition" aria-label="Permalink to &quot;Personnaliser la disposition&quot;">​</a></h3><p><strong>Éditer le layout</strong> passe le tableau de bord en mode édition : déplacez et redimensionnez les cartes, retirez-en une par son bouton <strong>Retirer</strong> (en haut à droite de la carte), ouvrez la <strong>Bibliothèque…</strong> (« Bibliothèque de widgets ») pour <strong>Ajouter</strong> ou <strong>Retirer</strong> des widgets, puis <strong>Enregistrer le layout</strong>. La disposition est enregistrée pour ce projet ; <strong>Réinitialiser</strong> revient à la disposition par défaut.</p><p>La bibliothèque garde aussi les anciennes cartes Phase, Épic en cours, Story &amp; tâche, Tâches et Mode de travail. Deux d&#39;entre elles agissent :</p><ul><li><strong>Phase</strong> : <strong>Détails / Avancer</strong> ouvre le tiroir « Cycle de vie — phase », avec les <strong>Documents requis</strong> de la phase courante et le bouton <strong>Avancer la phase</strong> quand la story est éligible ;</li><li><strong>Mode de travail</strong> : change le mode du projet, comme les <a href="/Effortless/guide/settings.html">Réglages du projet</a>.</li></ul><h2 id="avec-un-agent-ia" tabindex="-1">Avec un agent IA <a class="header-anchor" href="#avec-un-agent-ia" aria-label="Permalink to &quot;Avec un agent IA&quot;">​</a></h2><p><code>effortless_attention</code> rend exactement ce que montre cet écran — la ligne en cours, les points qui attendent, les statistiques et la file à suivre — avec un message lisible. L&#39;agent et vous voyez la même liste, calculée au même endroit.</p>',6))])}const b=a(d,[["render",c]]);export{q as __pageData,b as default};
